#include <vector>

class Solution {
public:
    int countMatchingSubarrays(std::vector<int>& nums, std::vector<int>& pattern) {
        auto sgn = [](int x) { return x > 0 ? 1 : (x < 0 ? -1 : 0); };
        std::vector<int> diff;
        for (size_t i = 0; i < nums.size() - 1; ++i) diff.push_back(sgn(nums[i + 1] - nums[i]));
        int m = pattern.size();
        std::vector<int> pi(m, 0);
        int j = 0;
        for (int i = 1; i < m; ++i) {
            while (j > 0 && pattern[i] != pattern[j]) j = pi[j - 1];
            if (pattern[i] == pattern[j]) j++;
            pi[i] = j;
        }
        int ans = 0;
        j = 0;
        for (int x : diff) {
            while (j > 0 && x != pattern[j]) j = pi[j - 1];
            if (x == pattern[j]) j++;
            if (j == m) {
                ans++;
                j = pi[j - 1];
            }
        }
        return ans;
    }
};

class Solution {
    public int countMatchingSubarrays(int[] nums, int[] pattern) {
        int n = nums.length;
        int[] diff = new int[n - 1];
        for (int i = 0; i < n - 1; ++i) {
            int d = nums[i + 1] - nums[i];
            diff[i] = d > 0 ? 1 : (d < 0 ? -1 : 0);
        }
        int m = pattern.length;
        int[] pi = new int[m];
        int j = 0;
        for (int i = 1; i < m; ++i) {
            while (j > 0 && pattern[i] != pattern[j]) j = pi[j - 1];
            if (pattern[i] == pattern[j]) j++;
            pi[i] = j;
        }
        int ans = 0;
        j = 0;
        for (int x : diff) {
            while (j > 0 && x != pattern[j]) j = pi[j - 1];
            if (x == pattern[j]) j++;
            if (j == m) {
                ans++;
                j = pi[j - 1];
            }
        }
        return ans;
    }
}

var countMatchingSubarrays = function(nums, pattern) {
    const sgn = x => x > 0 ? 1 : (x < 0 ? -1 : 0);
    const diff = [];
    for (let i = 0; i < nums.length - 1; ++i) diff.push(sgn(nums[i + 1] - nums[i]));
    const m = pattern.length;
    const pi = new Array(m).fill(0);
    let j = 0;
    for (let i = 1; i < m; ++i) {
        while (j > 0 && pattern[i] !== pattern[j]) j = pi[j - 1];
        if (pattern[i] === pattern[j]) j++;
        pi[i] = j;
    }
    let ans = 0;
    j = 0;
    for (const x of diff) {
        while (j > 0 && x !== pattern[j]) j = pi[j - 1];
        if (x === pattern[j]) j++;
        if (j === m) {
            ans++;
            j = pi[j - 1];
        }
    }
    return ans;
};
